        else
            alpha = 1.0f;

        alpha = alpha - (Sin(pulse_progress * 6.2831855f) + 1.0f) * 0.5f * alpha * 0.5f;
        OSDPrintUV(
            91,
            560.0f,
            70.0f,
            64.0f,
            396.0f,
            0x1000000,
            color.Set(1.0f, 1.0f, 1.0f, alpha),
            0.0f,
            0.0f,
            1.0f,
            0.7734375f,
            3,
            0);
    }

    float mask_v = mask_height * 0.001953125f;
    OSDPrintUV(
        89,
        560.0f,
        70.0f,
        64.0f,
        mask_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        0.0f,
        1.0f,
        mask_v,
        3,
        0);

    OSDPrintUV(
        90,
        560.0f,
        mask_height + 70.0f,
        64.0f,
        396.0f - mask_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        mask_v,
        1.0f,
        0.7734375f,
        3,
        0);
}

    float alpha;
    GameRoot* game = g_game;
    if (!game->subgame.subgame_pause_gate) {
        display_fill = (fill - display_fill) * 0.2f + display_fill;

        if (hit_flash_progress > 0.0f) {
            alpha = hit_flash_step + hit_flash_progress;
            hit_flash_progress = alpha;
            if (alpha > 1.0f)
                hit_flash_progress = 0.0f;
        }

        switch (state) {
        case DAMAGE_GUAGE_STATE_MONITORING: {
            if (*(int*)&fill == 0x3f800000) {
                game = g_game;
                if (game->subgame.embedded_player()->attachment_exit_pending
                    || game->subgame.embedded_player()->completion_handoff_active)
                    goto render;
                state = DAMAGE_GUAGE_STATE_WARNING_TRANSITION;
                warning_transition_progress = 0.0f;
                warning_transition_step = 0.16666667f;
                g_game->subgame.embedded_player()->warning.Start();
            }
            goto render_after_refresh;
        }

        case DAMAGE_GUAGE_STATE_WARNING_TRANSITION: {
            if (g_game->subgame.embedded_player()->completion_handoff_active)
                warning_transition_progress = 1.0f;
            alpha = warning_transition_step + warning_transition_progress;
            warning_transition_progress = alpha;
            if (alpha >= 1.0f) {
                game = g_game;
                if (*(int*)&game->subgame.embedded_player()->transform.position.y != 0x3efae148)
                    goto render;
                state = DAMAGE_GUAGE_STATE_DRAINING;
                g_voice_manager.Play(
                    VOICE_SET_POSTAL, VOICE_PLAY_IF_IDLE, -1);
            }
            goto render_after_refresh;
        }

        case DAMAGE_GUAGE_STATE_DRAINING: {
            GameRoot* skin_game = g_game;
            skin_game->subgame.embedded_player()
                ->presentation.snail_skin.Change(
                    SNAIL_SKIN_SLOT_DAMAGE, 0.2f);
            Take(-0.0016666667f, 1);
            skin_hold_ticks = 5;
            game = g_game;
            if (game->subgame.embedded_player()->completion_handoff_active) {
                Take(-0.0066666668f, 0);
                game = g_game;
            }
            if ((fill == 0.0f
                    && *(int*)&game->subgame.embedded_player()->transform.position.y == 0x3efae148)
                || game->subgame.embedded_player()->completion_handoff_timer > 0.0f
                || game->subgame.embedded_player()->resurrect_progress > 0.0f
                || game->subgame.embedded_player()->presentation.cutscene.state) {
                state = DAMAGE_GUAGE_STATE_MONITORING;
                g_game->subgame.embedded_player()->warning.Stop();
                g_game->subgame.embedded_player()->warning.StopSample();
                goto render_after_refresh;
            }
            break;
        }

        default:
render_after_refresh:
            game = g_game;
        }
    }

render:
    float mask_height;
    if (display_fill > 0.99900001f) {
        mask_height = 0.0f;
    } else if (display_fill < 0.0099999998f) {
        mask_height = 396.0f;
    } else {
        mask_height = 351.0f - display_fill * 308.0f;
    }

    if (!game->subgame.subgame_pause_gate)
        pulse_progress = pulse_step + pulse_progress;
    if (pulse_progress > 1.0f)
        pulse_progress = pulse_progress - 1.0f;

    tColour color;
    if (display_fill > 0.89999998f || state) {
        if (display_fill > 0.89999998f) {
            if (!state)
                alpha = (display_fill - 0.89999998f) * 10.0f;
            else
                alpha = 1.0f;
        } else if (display_fill < 0.1f)
            alpha = display_fill * 10.0f;
        else
            alpha = 1.0f;

        alpha = alpha - (Sin(pulse_progress * 6.2831855f) + 1.0f) * 0.5f * alpha * 0.5f;
        OSDPrintUV(
            91,
            560.0f,
            70.0f,
            64.0f,
            396.0f,
            0x1000000,
            color.Set(1.0f, 1.0f, 1.0f, alpha),
            0.0f,
            0.0f,
            1.0f,
            0.7734375f,
            3,
            0);
    }

    float mask_v = mask_height * 0.001953125f;
    OSDPrintUV(
        89,
        560.0f,
        70.0f,
        64.0f,
        mask_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        0.0f,
        1.0f,
        mask_v,
        3,
        0);

    OSDPrintUV(
        90,
        560.0f,
        mask_height + 70.0f,
        64.0f,
        396.0f - mask_height,
        0x1000000,
        color.Set(1.0f, 1.0f, 1.0f, 1.0f),
        0.0f,
        mask_v,
        1.0f,
        0.7734375f,
        3,
        0);
}
